"""DTAK logo: the single source of truth. Every file in logo/ is generated by this script.

    python3 -I tools/make_logo.py logo        (run from dtak-image/; needs tools/requirements.txt)

Writes, as SVG (all text outlined, no fonts needed to display) plus PNG renders in logo/png/:
  dtak_long[_dark]      icon · DTAK | two-line tagline     main logo
  dtak_short[_dark]     icon · DTAK                        compact logo (slides footer, small sizes)
  dtak_box              white icon on a UPC-blue square     avatar, favicon, social media

Geometry (all in font units of Montserrat Bold, cap height CAP = 700):
  * The icon is a 7-node network (3 large-role "navy", 2 "blue", 2 "soft" nodes, 9 edges).
  * long/short: icon height = 1.42 × CAP, so DTAK's cap height covers the middle 70 % of the logo height:
    the same band as the UPC mark's text block next to its disc. The SVG has NO padding: the icon touches the
    top and bottom edges, exactly like the UPC mark's file. Same height in a layout = equal footing.
  * DTAK: Montserrat Bold, the font's default kerning (GPOS), the A drawn without its crossbar (open A).
  * tagline: "Data to knowledge" / "Data for knowledge", Helvetica Neue Roman (outlined), "to"/"for" in the accent.
"""
import json
import os
import sys
from pathlib import Path

import pathops
import uharfbuzz as hb
from fontTools.pens.recordingPen import RecordingPen
from fontTools.pens.svgPathPen import SVGPathPen
from fontTools.pens.transformPen import TransformPen
from fontTools.ttLib import TTFont

HERE = Path(__file__).resolve().parent.parent
WORDMARK = HERE / 'fonts/Montserrat-Bold.ttf'  # SIL OFL, bundled
# Helvetica Neue is a licensed font: not bundled. Only needed to regenerate (the SVGs are outlined).
TAGFONT = Path(os.environ.get('DTAK_TAGLINE_FONT', Path.home() / '.local/share/fonts/helvetica-neue/HelveticaNeueRoman.otf'))
TEXT = 'DTAK'
LINES = [('Data ', 'to', ' knowledge'), ('Data ', 'for', ' knowledge')]  # (text, accent, text)

# ---- colors ----
NAVY = '#0A2A4F'      # DTAK navy: D, T, K, tagline, 3 nodes; also the dark background
UPC = '#0076CF'       # UPC blue, Pantone 2195 (UPC identity manual): open A, to/for, 2 nodes, box background
WHITE = '#FFFFFF'
EDGE_TINT = 0.5      # edges + divider on light backgrounds: navy at 50 % over white (a desaturated navy)
SOFT_TINT = 0.6      # Soft blue: desaturated UPC blue, used in some nodes; replaces UPC blue on dark backgrounds


def tint(color, t):
    """`color` at opacity t over white, as #RRGGBB."""
    return '#' + ''.join('%02X' % round(int(color[i:i + 2], 16) * t + 255 * (1 - t)) for i in (1, 3, 5))


EDGE = tint(NAVY, EDGE_TINT)  # = #8494A7
UPC_SOFT = tint(UPC, SOFT_TINT)  # = #66ADE2
PAL = {
    # light background: 4 colors
    'light': dict(navy=NAVY, blue=UPC, soft=UPC_SOFT, edge=EDGE, text=NAVY, accent=UPC),
    # dark background: 2 colors only (white + soft UPC blue)
    'dark': dict(navy=WHITE, blue=UPC_SOFT, soft=UPC_SOFT, edge=WHITE, text=WHITE, accent=UPC_SOFT),
    # box: white icon on UPC blue
    'box': dict(navy=WHITE, blue=WHITE, soft=WHITE, edge=WHITE, text=WHITE, accent=WHITE),
}

# ---- icon: (x, y, r, role) in icon units; edges are pairs of node indices ----
NODES = [(25.5, 36.5, 15, 'navy'), (274, 77, 15, 'navy'), (86, 137.5, 40, 'navy'),
         (187, 36, 26.5, 'blue'), (166.5, 251.5, 18, 'blue'),
         (240.5, 177.5, 23, 'soft'), (45.5, 238, 15, 'soft')]
EDGES = [(0, 2), (0, 3), (1, 3), (2, 3), (2, 4), (2, 5), (2, 6), (3, 5), (4, 5)]
EDGE_W = 6

# ---- layout, as multiples of the DTAK cap height ----
CAP = 700
ICON_H = 1.42       # icon height (= logo height of long/short)
ICON_GAP = 0.35     # icon → DTAK
DIV_GAP = 0.40      # DTAK → divider, divider → tagline; divider height = CAP
TAG_CAP = 0.28      # tagline cap height
TAG_LEAD = 0.474    # tagline baseline-to-baseline
BOX_PAD = 0.16      # box: margin around the icon, as a fraction of the square's side

PNG_HEIGHT = {'dtak_long': 512, 'dtak_short': 512, 'dtak_box': 1024}


def path_d(p):
    pen = SVGPathPen(None)
    p.draw(pen)
    return pen.getCommands()


# ---------------------------------------------------------------- icon
def icon_bounds():
    xs = [x - r for x, y, r, _ in NODES] + [x + r for x, y, r, _ in NODES]
    ys = [y - r for x, y, r, _ in NODES] + [y + r for x, y, r, _ in NODES]
    return min(xs), min(ys), max(xs), max(ys)


def icon_aspect():
    bx0, by0, bx1, by1 = icon_bounds()
    return (bx1 - bx0) / (by1 - by0)


def icon(pal, x0, y0, height):
    """Icon scaled to `height`, top-left at (x0, y0). Returns (svg, width, edge stroke width)."""
    bx0, by0, bx1, by1 = icon_bounds()
    s = height / (by1 - by0)
    X = lambda x: x0 + (x - bx0) * s
    Y = lambda y: y0 + (y - by0) * s
    out = ['<g id="icon">', f'  <g id="edges" stroke="{pal["edge"]}" stroke-width="{EDGE_W * s:.2f}">']
    for i, j in EDGES:
        (xa, ya, *_), (xb, yb, *_) = NODES[i], NODES[j]
        out.append(f'    <line x1="{X(xa):.1f}" y1="{Y(ya):.1f}" x2="{X(xb):.1f}" y2="{Y(yb):.1f}"/>')
    out.append('  </g>')
    for x, y, r, role in NODES:
        out.append(f'  <circle cx="{X(x):.1f}" cy="{Y(y):.1f}" r="{r * s:.1f}" fill="{pal[role]}"/>')
    out.append('</g>')
    return '\n'.join(out), (bx1 - bx0) * s, EDGE_W * s


# ---------------------------------------------------------------- DTAK
def open_a(contours, cap):
    """Keep only the contours that reach the cap height: the A without its crossbar."""
    keep = [c for c in contours if max(p[1] for _, a in c for p in a) >= cap - 1]
    assert len(keep) < len(contours), 'no separate crossbar contour found'
    return keep


def glyph_path(gs, name, dx, lam):
    rec = RecordingPen()
    gs[name].draw(rec)
    contours, cur = [], []
    for op, args in rec.value:
        cur.append((op, args))
        if op in ('closePath', 'endPath'):
            contours.append(cur)
            cur = []
    if lam:
        contours = open_a(contours, CAP)
    p = pathops.Path()
    tp = TransformPen(p.getPen(), (1, 0, 0, -1, dx, 0))  # y down
    for c in contours:
        for op, args in c:
            getattr(tp, op)(*args)
    p.simplify()
    return p


def shape(fontfile, text):
    font = hb.Font(hb.Face(hb.Blob.from_file_path(str(fontfile))))
    buf = hb.Buffer()
    buf.add_str(text)
    buf.guess_segment_properties()
    hb.shape(font, buf, {'kern': True, 'liga': False})
    return buf.glyph_infos, buf.glyph_positions


TT_WM = TTFont(WORDMARK)
assert TT_WM['OS/2'].sCapHeight == CAP and TT_WM['head'].unitsPerEm == 1000


def wordmark(pal, x0, baseline):
    """DTAK at cap height CAP, ink starting at x0. Default (GPOS) kerning. Returns (svg, ink width)."""
    gs, order = TT_WM.getGlyphSet(), TT_WM.getGlyphOrder()
    glyphs, x = [], 0
    for ch, info, gp in zip(TEXT, *shape(WORDMARK, TEXT)):
        glyphs.append((ch, glyph_path(gs, order[info.codepoint], x + gp.x_offset, ch == 'A')))
        x += gp.x_advance
    lx = min(p.bounds[0] for _, p in glyphs)
    rx = max(p.bounds[2] for _, p in glyphs)
    out = ['<g id="DTAK">'] + [
        f'  <path id="{ch}" transform="translate({x0 - lx:.1f} {baseline:.1f})" '
        f'fill="{pal["accent"] if ch == "A" else pal["text"]}" d="{path_d(p)}"/>'
        for ch, p in glyphs] + ['</g>']
    return '\n'.join(out), rx - lx


# ---------------------------------------------------------------- tagline
TT_TAG = TTFont(TAGFONT)
TAG_UPM = TT_TAG['head'].unitsPerEm
TAG_SIZE = TAG_CAP * CAP * TAG_UPM / TT_TAG['OS/2'].sCapHeight  # font size giving TAG_CAP


def line_width(runs, size=TAG_SIZE):
    return sum(p.x_advance for p in shape(TAGFONT, ''.join(runs))[1]) * size / TAG_UPM


def tagline(pal, x0, first_baseline, size=TAG_SIZE, align='left', width=0):
    gs, order = TT_TAG.getGlyphSet(), TT_TAG.getGlyphOrder()
    k = size / TAG_UPM
    out = ['<g id="tagline">']
    for n, runs in enumerate(LINES):
        a0, a1 = len(runs[0]), len(runs[0]) + len(runs[1])
        infos, pos = shape(TAGFONT, ''.join(runs))
        lx = x0 + ((width - line_width(runs, size)) / 2 if align == 'center' else 0)
        base = first_baseline + n * TAG_LEAD * CAP * size / TAG_SIZE
        paths = {'text': pathops.Path(), 'accent': pathops.Path()}
        x = 0
        for info, gp in zip(infos, pos):
            tgt = paths['accent' if a0 <= info.cluster < a1 else 'text']
            gs[order[info.codepoint]].draw(TransformPen(tgt.getPen(), (k, 0, 0, -k, lx + (x + gp.x_offset) * k, base)))
            x += gp.x_advance
        for p in paths.values():
            p.simplify()
        out += [f'  <path fill="{pal["text"]}" d="{path_d(paths["text"])}"/>',
                f'  <path id="{runs[1]}" fill="{pal["accent"]}" d="{path_d(paths["accent"])}"/>']
    return '\n'.join(out + ['</g>'])


# ---------------------------------------------------------------- files
def svg(body, w, h, title, px_h):
    """Tight viewBox (no padding), like the UPC mark's own SVG. Default size: px_h pixels tall."""
    return (f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {w:.1f} {h:.1f}" '
            f'width="{w / h * px_h:.1f}" height="{px_h}">\n<title>{title}</title>\n{body}\n</svg>\n')


def build(out):
    out.mkdir(parents=True, exist_ok=True)
    _, wm_w = wordmark(PAL['light'], 0, 0)
    tag_cap, lead = TAG_CAP * CAP, TAG_LEAD * CAP
    tag_w = max(line_width(r) for r in LINES)
    files = []
    for mode in ('light', 'dark'):
        pal, sfx = PAL[mode], '' if mode == 'light' else '_dark'
        on = 'light' if mode == 'light' else 'dark'

        def write(name, body, w, h, what, px_h):
            (out / f'{name}{sfx}.svg').write_text(svg(body, w, h, f'DTAK {what}, for {on} backgrounds', px_h))
            files.append(f'{name}{sfx}')

        # short + long
        ih = ICON_H * CAP
        ic, iw, edge_w = icon(pal, 0, 0, ih)
        x = iw + ICON_GAP * CAP
        base = (ih + CAP) / 2  # DTAK vertically centred on the icon
        wm, _ = wordmark(pal, x, base)
        write('dtak_short', ic + '\n' + wm, x + wm_w, ih, 'short logo', 61)
        dx = x + wm_w + DIV_GAP * CAP
        div = (f'<line id="divider" x1="{dx:.1f}" y1="{base - CAP:.1f}" x2="{dx:.1f}" y2="{base:.1f}" '
               f'stroke="{pal["edge"]}" stroke-width="{edge_w:.2f}"/>')
        tx = dx + DIV_GAP * CAP
        first = base - CAP / 2 - (tag_cap + lead) / 2 + tag_cap  # two lines centred on DTAK
        write('dtak_long', '\n'.join([ic, wm, div, tagline(pal, tx, first)]), tx + tag_w, ih, 'logo', 61)

    # box: square in UPC blue, white icon centred
    side = 1000
    ih = side * (1 - 2 * BOX_PAD) / max(1, icon_aspect())
    iw = ih * icon_aspect()
    ic = icon(PAL['box'], (side - iw) / 2, (side - ih) / 2, ih)[0]
    body = f'<rect id="box" width="{side}" height="{side}" fill="{UPC}"/>\n{ic}'
    (out / 'dtak_box.svg').write_text(svg(body, side, side, 'DTAK icon on UPC blue', 160))
    files.append('dtak_box')
    return files


def export_png(out, names):
    import cairosvg
    from PIL import Image
    png = out / 'png'
    png.mkdir(exist_ok=True)
    sizes = {}
    for name in names:
        h = PNG_HEIGHT[name.removesuffix('_dark')]
        cairosvg.svg2png(url=str(out / f'{name}.svg'), write_to=str(png / f'{name}.png'), output_height=h)
        sizes[name] = Image.open(png / f'{name}.png').size
    return sizes


if __name__ == '__main__':
    out = Path(sys.argv[1] if len(sys.argv) > 1 else HERE / 'logo')
    names = build(out)
    sizes = export_png(out, names)
    for n in names:
        print(f'{n:20} {sizes[n][0]}x{sizes[n][1]} png')
